model User {
  id    String @id @default(uuid())
  posts Post[] // Virtual relation field (no DB column)
}

model Post {
  id       String @id @default(uuid())
  authorId String @map("author_id") // Physical foreign key column in PostgreSQL
  author   User   @relation(fields: [authorId], references: [id]) // Virtual relation link
}
